// src/components/BackButton.jsx
import React from "react";
import { useNavigate } from "react-router-dom";

export default function BackButton() {
  const navigate = useNavigate();
  return (
    <button
      onClick={() => navigate(-1)}
      style={{
        marginBottom: "20px",
        backgroundColor: "#ddd",
        border: "none",
        padding: "8px 12px",
        borderRadius: "4px",
        cursor: "pointer",
      }}
    >
      ⬅️ Back
    </button>
  );
}
